<?php
declare(strict_types=1);
use MiniErp\Fiscal\FiscalArtifactStorage;use MiniErp\Repositories\FiscalArtifactRepository;use MiniErp\Services\{FiscalDanfeException,FiscalDanfeService};
require_once __DIR__.'/../vendor/autoload.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();$tenantId=(int)($_SESSION['erp_tenant_id']??$_SESSION['tenant_id']??0);$userId=(int)($_SESSION['erp_user_id']??$_SESSION['user_id']??0);if($tenantId<1||$userId<1){http_response_code(401);exit('Sessão expirada.');}session_write_close();$artifactId=filter_input(INPUT_GET,'artifact_id',FILTER_VALIDATE_INT)?:0;$mode=($_GET['mode']??'inline')==='download'?'attachment':'inline';try{$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$main=new PDO("mysql:host={$d['host']};port={$d['port']};dbname={$d['database']};charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$s=$main->prepare('SELECT db_name FROM tenants WHERE id=?');$s->execute([$tenantId]);$db=(string)$s->fetchColumn();if(!preg_match('/^mini_erp_tenant_[1-9]\d*$/',$db))throw new RuntimeException('Tenant inválido.');$pdo=new PDO("mysql:host={$d['host']};port={$d['port']};dbname={$db};charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$service=new FiscalDanfeService(new FiscalArtifactRepository($pdo,$tenantId),new FiscalArtifactStorage(__DIR__.'/../storage/fiscal/artifacts'),__DIR__.'/../storage/fiscal/danfe');$result=$service->render($artifactId);$name=str_replace(['"',"\r","\n"],'',(string)$result['filename']);header('Content-Type: application/pdf');header('Content-Disposition: '.$mode.'; filename="'.$name.'"');header('Content-Length: '.strlen($result['bytes']));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');echo$result['bytes'];}catch(FiscalDanfeException$e){http_response_code(in_array($e->errorCode,['DANFE_ARTIFACT_NOT_FOUND','DANFE_ACCESS_DENIED'],true)?404:422);header('Content-Type: text/plain; charset=utf-8');echo$e->getMessage();}catch(Throwable){http_response_code(500);header('Content-Type: text/plain; charset=utf-8');echo'Não foi possível gerar o DANFE.';}
